<?php
$pdo=db();$tab=(string)($_GET['tab']??'classes');if(!in_array($tab,['classes','subjects','terms','assessments','grading','timetable'],true))$tab='classes';$canManage=in_array($user['role'],['Administrator','Head'],true);
$classSql="SELECT c.id,c.form_level,c.stream,c.academic_year,c.class_teacher_id,u.full_name AS class_teacher,COUNT(DISTINCT s.id) AS learners FROM class_groups c LEFT JOIN users u ON u.id=c.class_teacher_id LEFT JOIN students s ON s.form_level=c.form_level AND COALESCE(s.stream,'')=c.stream AND s.status='Active'";
$classParams=[];if($user['role']==='Teacher'){$classSql.=' WHERE c.class_teacher_id=:teacher_class OR EXISTS (SELECT 1 FROM class_subjects assigned WHERE assigned.class_id=c.id AND assigned.teacher_id=:teacher_subject)';$classParams=['teacher_class'=>$user['id'],'teacher_subject'=>$user['id']];}
$classSql.=' GROUP BY c.id,c.form_level,c.stream,c.academic_year,c.class_teacher_id,u.full_name ORDER BY c.academic_year DESC,c.form_level,c.stream';$classQuery=$pdo->prepare($classSql);$classQuery->execute($classParams);$classes=$classQuery->fetchAll();
$subjects=$pdo->query('SELECT id,subject_code,subject_name,level,active FROM subjects ORDER BY subject_name')->fetchAll();
$teachers=$pdo->query("SELECT id,full_name FROM users WHERE role='Teacher' AND active=1 ORDER BY full_name")->fetchAll();
$terms=$pdo->query('SELECT * FROM school_terms ORDER BY academic_year DESC,term_number DESC')->fetchAll();
$assignmentSql='SELECT cs.id,c.form_level,c.stream,c.academic_year,s.subject_code,s.subject_name,u.full_name AS teacher FROM class_subjects cs JOIN class_groups c ON c.id=cs.class_id JOIN subjects s ON s.id=cs.subject_id LEFT JOIN users u ON u.id=cs.teacher_id';
$assignmentParams=[];if($user['role']==='Teacher'){$assignmentSql.=' WHERE cs.teacher_id=:teacher_subject OR c.class_teacher_id=:teacher_class';$assignmentParams=['teacher_subject'=>$user['id'],'teacher_class'=>$user['id']];}$assignmentSql.=' ORDER BY c.academic_year DESC,c.form_level,c.stream,s.subject_name';$assignmentQuery=$pdo->prepare($assignmentSql);$assignmentQuery->execute($assignmentParams);$assignments=$assignmentQuery->fetchAll();
$editTermId=filter_var($_GET['edit_term']??null,FILTER_VALIDATE_INT);$editTerm=null;if($editTermId)foreach($terms as $candidate)if((int)$candidate['id']===$editTermId){$editTerm=$candidate;break;}$defaultTerm=(int)date('n')<=4?1:((int)date('n')<=8?2:3);
?>
