<?php if($tab==='assessments'): require __DIR__ . '/assessments.php'; elseif($tab==='grading'): if($canManage)require __DIR__ . '/grading.php';else echo '<div class="alert alert-error">Only school administrators and heads can manage grading scales.</div>'; elseif($tab==='timetable'): require __DIR__ . '/timetable.php'; elseif($tab==='classes'): ?>
