  <section class="panel settings-panel"><h2>Assign a subject</h2><p>Only active subject and teacher records are available.</p><form method="post" action="actions/class_subject_save.php" class="compact-form"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><label>Class<select name="class_id" required><option value="">Select class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>">Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?> · <?= (int)$class['academic_year'] ?></option><?php endforeach; ?></select></label><label>Subject<select name="subject_id" required><option value="">Select subject</option><?php foreach($subjects as $subject): if($subject['active']): ?><option value="<?= (int)$subject['id'] ?>"><?= h($subject['subject_name']) ?> (<?= h($subject['subject_code']) ?>)</option><?php endif; endforeach; ?></select></label><label>Subject teacher<select name="teacher_id"><option value="">Use class teacher / unassigned</option><?php foreach($teachers as $teacher): ?><option value="<?= (int)$teacher['id'] ?>"><?= h($teacher['full_name']) ?></option><?php endforeach; ?></select></label><button class="primary-button">Save subject assignment</button></form></section></div><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Class groups</h2><p><?= count($classes) ?> group<?= count($classes)===1?'':'s' ?> configured</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Class</th><th>Academic year</th><th>Class teacher</th><th>Active learners</th><th>Subjects</th></tr></thead><tbody><?php foreach($classes as $class): ?><tr><td>Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?> <span class="level-chip"><?= $class['form_level']<=4?'O-Level':'A-Level' ?></span></td><td><?= (int)$class['academic_year'] ?></td><td><?= h($class['class_teacher']?:'Unassigned') ?></td><td><?= (int)$class['learners'] ?></td><td><?php $count=$pdo->prepare('SELECT COUNT(*) FROM class_subjects WHERE class_id=:id');$count->execute(['id'=>$class['id']]);echo (int)$count->fetchColumn(); ?></td></tr><?php endforeach; if(!$classes): ?><tr><td colspan="5" class="empty-cell">No class groups yet. Add staff accounts and create the school’s streams.</td></tr><?php endif; ?></tbody></table></div></section>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Subject assignments</h2><p>Teaching allocations for each form and stream</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Class</th><th>Subject</th><th>Teacher</th></tr></thead><tbody><?php foreach($assignments as $a): ?><tr><td>Form <?= (int)$a['form_level'] ?><?= h($a['stream']) ?> · <?= (int)$a['academic_year'] ?></td><td><?= h($a['subject_name']) ?> <span class="muted-cell">(<?= h($a['subject_code']) ?>)</span></td><td><?= h($a['teacher']?:'Unassigned') ?></td></tr><?php endforeach; if(!$assignments): ?><tr><td colspan="3" class="empty-cell">No subject assignments yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php elseif($tab==='subjects'): ?>
  <?php if($canManage): ?><section class="panel settings-panel"><h2>Add a subject</h2><p>Maintain the subjects offered by your school. Codes are school-defined and can match ZIMSEC subjects.</p><form method="post" action="actions/subject_save.php" class="inline-form"><?= csrf_field() ?><label>Subject code<input name="subject_code" required maxlength="20" placeholder="ENG"></label><label>Subject name<input name="subject_name" required maxlength="100" placeholder="English Language"></label><label>Level<select name="level"><option>Both</option><option>O-Level</option><option>A-Level</option></select></label><button class="primary-button">Add subject</button></form></section><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Subject catalog</h2><p>O-Level and A-Level subjects currently configured</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Code</th><th>Subject</th><th>Level</th><th>Status</th><?php if($canManage): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($subjects as $subject): ?><tr><td><?= h($subject['subject_code']) ?></td><td><?= h($subject['subject_name']) ?></td><td><?= h($subject['level']) ?></td><td><span class="status-pill <?= $subject['active']?'':'inactive' ?>"><?= $subject['active']?'Active':'Inactive' ?></span></td><?php if($canManage): ?><td><form method="post" action="actions/subject_save.php" class="subject-edit-form"><?= csrf_field() ?><input type="hidden" name="subject_id" value="<?= (int)$subject['id'] ?>"><input type="hidden" name="subject_code" value="<?= h($subject['subject_code']) ?>"><input type="hidden" name="subject_name" value="<?= h($subject['subject_name']) ?>"><input type="hidden" name="level" value="<?= h($subject['level']) ?>"><input type="hidden" name="active" value="<?= $subject['active']?'0':'1' ?>"><button class="text-button"><?= $subject['active']?'Deactivate':'Activate' ?></button></form></td><?php endif; ?></tr><?php endforeach; if(!$subjects): ?><tr><td colspan="5" class="empty-cell">No subjects yet. Add the school’s subject catalog above.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?>
  <?php if($canManage): ?><section class="panel settings-panel"><h2><?= $editTerm?'Edit academic term':'Add an academic term' ?></h2><p>Define term dates and select one active term for the school.</p><form method="post" action="actions/term_save.php" class="inline-form term-form"><?= csrf_field() ?><?php if($editTerm): ?><input type="hidden" name="term_id" value="<?= (int)$editTerm['id'] ?>"><?php endif; ?><label>Academic year<input type="number" name="academic_year" min="2000" max="2100" required value="<?= h($editTerm['academic_year']??date('Y')) ?>"></label><label>Term number<select name="term_number"><?php for($i=1;$i<=3;$i++): ?><option value="<?= $i ?>" <?= (int)($editTerm['term_number']??$defaultTerm)===$i?'selected':'' ?>>Term <?= $i ?></option><?php endfor; ?></select></label><label>Term name<input name="name" required maxlength="60" value="<?= h($editTerm['name']??'Term '.$defaultTerm) ?>"></label><label>Starts<input type="date" name="starts_on" required value="<?= h($editTerm['starts_on']??'') ?>"></label><label>Ends<input type="date" name="ends_on" required value="<?= h($editTerm['ends_on']??'') ?>"></label><label class="consent-check"><input type="checkbox" name="is_current" value="1" <?= ($editTerm['is_current']??false)?'checked':'' ?>>Set as current term</label><button class="primary-button">Save term</button></form></section><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Term calendar</h2><p>Maintain the school’s term dates</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Academic year</th><th>Term</th><th>Dates</th><th>Status</th><?php if($canManage): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($terms as $term): ?><tr><td><?= (int)$term['academic_year'] ?></td><td><?= h($term['name']) ?></td><td><?= h(date('d M Y',strtotime($term['starts_on']))) ?> – <?= h(date('d M Y',strtotime($term['ends_on']))) ?></td><td><span class="status-pill <?= $term['is_current']?'':'inactive' ?>"><?= $term['is_current']?'Current':'Scheduled' ?></span></td><?php if($canManage): ?><td><a class="text-button" href="?page=academics&tab=terms&edit_term=<?= (int)$term['id'] ?>">Edit</a></td><?php endif; ?></tr><?php endforeach; if(!$terms): ?><tr><td colspan="5" class="empty-cell">No term dates configured yet.</td></tr><?php endif; ?></tbody></table></div></section>
